fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Assuming tol > 0 as per problem statement
    let diff = (a as i16) - (b as i16);
    let abs_diff = diff.abs();
    abs_diff < tol as i16
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions from problem:
    // a.len() == b.len() > 0
    // tol > 0

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}